const fs = require("fs");
const lockfile = JSON.parse(fs.readFileSync("package-lock.json", "utf8"));
const packages = lockfile.packages || {};

// Function to find installed version of a package
function getInstalledVersion(packageName) {
  for (const [path, pkg] of Object.entries(packages)) {
    const name = path.replace("node_modules/", "").split("/node_modules/").pop();
    if (name === packageName && pkg.version) {
      return pkg.version;
    }
  }
  return "N/A";
}

// npm audit data from our scan - HIGH and CRITICAL vulnerabilities
const auditData = {
  "@babel/traverse": {
    severity: "critical",
    cvss: 9.4,
