    url: "https://github.com/advisories/GHSA-3xgq-45jj-v275",
    range: ">=7.0.0 <7.0.5",
    fixedVersion: "7.0.5"
  },
  "ip": {
    severity: "high",
    cvss: 8.1,
    title: "ip SSRF improper categorization in isPublic",
    url: "https://github.com/advisories/GHSA-2p57-rm9w-gvfp",
    range: "<=2.0.1",
    fixedVersion: "N/A"
  },
  "json5": {
    severity: "high",
    cvss: 7.1,
    title: "Prototype Pollution in JSON5 via Parse Method",
    url: "https://github.com/advisories/GHSA-9c47-m6qq-7p4h",
    range: ">=2.0.0 <2.2.2",
    fixedVersion: "2.2.2"
  },
  "marked": {
    severity: "high",
    cvss: 7.5,
    title: "Inefficient Regular Expression Complexity in marked",
    url: "https://github.com/advisories/GHSA-rrrm-qjm4-v8hf",
    range: "<4.0.10",
    fixedVersion: "4.0.10"
  },
  "qs": {
    severity: "high",
    cvss: 7.5,
    title: "qs's arrayLimit bypass in its bracket notation allows DoS via memory exhaustion",
    url: "https://github.com/advisories/GHSA-6rw7-vpxm-498p",
    range: "<6.14.1",
    fixedVersion: "6.14.1"
  },
  "semver": {
    severity: "high",
