    title: "Uncaught Exception in yaml",
    url: "https://github.com/advisories/GHSA-f9xv-q969-pqx4",
    range: ">=2.0.0-5 <2.2.2",
    fixedVersion: "2.2.2"
  }
};

// GHSA to CVE mapping (from known sources)
const ghsaToCve = {
  "GHSA-67hx-6x53-jw92": "CVE-2023-45133",
  "GHSA-crh6-fp67-6883": "CVE-2022-39353",
  "GHSA-fjxv-7rqg-78g4": "CVE-2025-0553",
  "GHSA-p8p7-x288-28g6": "CVE-2023-28155",
  "GHSA-grv7-fg5c-xmjg": "CVE-2024-4068",
  "GHSA-3xgq-45jj-v275": "CVE-2024-21538",
  "GHSA-2p57-rm9w-gvfp": "CVE-2024-29415",
  "GHSA-9c47-m6qq-7p4h": "CVE-2022-46175",
  "GHSA-rrrm-qjm4-v8hf": "CVE-2022-21680",
  "GHSA-6rw7-vpxm-498p": "CVE-2025-21535",
  "GHSA-c2qf-rxjj-qqgw": "CVE-2022-25883",
  "GHSA-r6q2-hw4h-h46w": "CVE-2025-24803",
  "GHSA-pq67-2wwv-3xjx": "CVE-2024-46989",
  "GHSA-3h5v-q93c-6h6q": "CVE-2024-37890",
  "GHSA-f9xv-q969-pqx4": "CVE-2023-2251"
};

// Build the CSV
let csv = "Package,Version,CVE_ID,Severity,CVSS_Score,Fixed_Version,Title,Url\n";

for (const [pkg, data] of Object.entries(auditData)) {
  const version = getInstalledVersion(pkg);
  const ghsaId = data.url.split("/").pop();
  const cveId = ghsaToCve[ghsaId] || "N/A";
  const cvss = data.cvss !== null ? data.cvss.toString() : "N/A";

  // Escape fields for CSV
  const escapeCSV = (str) => {
    if (str.includes(",") || str.includes('"') || str.includes("\n")) {
      return '"' + str.replace(/"/g, '""') + '"';
    }
    return str;
  };

  csv += `${escapeCSV(pkg)},${escapeCSV(version)},${escapeCSV(cveId)},${escapeCSV(data.severity.toUpperCase())},${escapeCSV(cvss)},${escapeCSV(data.fixedVersion)},${escapeCSV(data.title)},${escapeCSV(data.url)}\n`;
}

console.log(csv);
fs.writeFileSync("security_audit.csv", csv);
console.log("\nWritten to security_audit.csv");

